INSERT IGNORE INTO UI_USER_EMAIL (USER_ID, USER_EMAIL, IS_AUTO)
VALUES ( #{userId},

	xcnenc(#{encryptAlgorithm}, #{encryptSize}, #{encryptKey}, #{userEmail} ),


	#{userEmail},

#{isAuto}
)

mapper.select:
SELECT	COUNT(*) AS CNT
FROM	UI_USERS
WHERE	USER_ID	= #{userId}

SELECT	COUNT(*) AS CNT
FROM	UI_USER_GROUP
WHERE	GROUP_CODE	= #{groupCode}

mapper.update:
UPDATE	UI_USER_GROUP
SET		GROUP_NAME = #{groupName}
WHERE	GROUP_CODE = #{groupCode}

mapper.select:
SELECT  USER_EMAIL AS userEmail, USER_IP AS userIp
FROM  UI_USER_EMAIL
JOIN UI_USER_IP ON UI_USER_EMAIL.USER_ID = UI_USER_IP.USER_ID
WHERE  UI_USER_EMAIL.USER_ID = #{userid}
LIMIT 1;

SELECT	COUNT(*) AS CNT
FROM	UI_USER_GROUP_LIST
WHERE	GROUP_CODE = #{groupCode}
AND		USER_ID = #{userId}

mapper.delete:
DELETE
FROM	UI_USER_GROUP_LIST
WHERE	GROUP_CODE = #{groupCode}

AND		LIST_SEQ = #{listSeq}

mapper.select:
SELECT 	GROUP_CONCAT( CONCAT(SERVICECD, #{subDelimiter}, ACCOUNT) SEPARATOR #{mainDelimiter})
FROM 	UI_USER_ACCOUNT
WHERE 	USER_ID = #{userId}

SELECT  GROUP_CONCAT(ACCOUNT SEPARATOR ', ')
FROM    UI_USER_ACCOUNT
WHERE   SERVICECD = #{svc12}
AND   USER_ID = #{userId}

SELECT  USER_ID as userId
FROM    UI_USER_ACCOUNT
WHERE   SERVICECD = #{svc12}
AND     ACCOUNT = #{sender}
Limit 1
